import React, { useRef, useEffect, useState } from 'react';

function useVisible(threshold = 0.1) {
  const ref = useRef(null);
  const [vis, setVis] = useState(false);

  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) setVis(true);
      },
      { threshold }
    );

    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [threshold]);

  return [ref, vis];
}

const projects = [
  {
    title: 'Hotel Reservation Website',
    desc: 'Website reservasi hotel untuk pemesanan kamar dan pengelolaan data reservasi menggunakan CodeIgniter 4 dan MySQL.',
    tech: ['CodeIgniter 4', 'PHP', 'MySQL', 'Web App'],
    color: 'var(--sky)',
    accent: '#4a90d9',
    tag: 'Web App',
    image: '/images/hotel.png',
  },
  {
    title: 'Daily Challenge App',
    desc: 'Aplikasi mobile checklist aktivitas sehari-hari yang membantu pengguna mencatat dan menandai aktivitas yang sudah selesai.',
    tech: ['Flutter', 'Firebase', 'Dart', 'Mobile App'],
    color: 'var(--rose)',
    accent: 'var(--rose-deep)',
    tag: 'Mobile App',
    image: '/images/daily-challenge.png',
  },
  {
    title: 'Daily Challenge UI Design',
    desc: 'Desain antarmuka aplikasi Daily Challenge dengan tampilan sederhana, modern, dan mudah digunakan oleh pengguna.',
    tech: ['Canva', 'UI Design', 'Mobile Design'],
    color: 'var(--lavender)',
    accent: 'var(--lav-deep)',
    tag: 'UI Design',
    image: '/images/daily-ui.png',
  },
];

function ProjectCard({ project, index, vis }) {
  const [hovered, setHovered] = useState(false);

  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        background: 'var(--card-bg)',
        border: `1.5px solid ${
          hovered ? project.accent : 'rgba(255,255,255,0.08)'
        }`,
        borderRadius: 'var(--radius-lg)',
        padding: '1.2rem',
        cursor: 'pointer',
        transition: 'all 0.4s cubic-bezier(.4,0,.2,1)',
        transform: vis
          ? hovered
            ? 'translateY(-8px) scale(1.02)'
            : 'translateY(0) scale(1)'
          : 'translateY(30px) scale(0.97)',
        opacity: vis ? 1 : 0,
        transitionDelay: `${index * 0.1}s`,
        boxShadow: hovered
          ? `0 20px 60px ${project.accent}45`
          : '0 4px 20px rgba(0,0,0,0.25)',
        backdropFilter: 'blur(10px)',
        display: 'flex',
        flexDirection: 'column',
        gap: '1rem',
        minHeight: '430px',
      }}
    >
      <div
        style={{
          height: 190,
          borderRadius: 'var(--radius-md)',
          overflow: 'hidden',
          position: 'relative',
          background: '#111',
        }}
      >
        <img
          src={project.image}
          alt={project.title}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            transition: 'transform 0.5s ease',
            transform: hovered ? 'scale(1.08)' : 'scale(1)',
          }}
        />

        <div
          style={{
            position: 'absolute',
            inset: 0,
            background:
              'linear-gradient(to bottom, rgba(0,0,0,0.05), rgba(0,0,0,0.65))',
          }}
        />

        <span
          style={{
            position: 'absolute',
            bottom: 14,
            left: 14,
            background: project.accent,
            color: '#fff',
            padding: '0.35rem 0.85rem',
            borderRadius: '99px',
            fontSize: '0.75rem',
            fontWeight: 600,
          }}
        >
          {project.tag}
        </span>
      </div>

      <h3
        style={{
          fontFamily: 'var(--font-display)',
          fontWeight: 700,
          fontSize: '1.35rem',
          lineHeight: 1.3,
          color: 'var(--text)',
        }}
      >
        {project.title}
      </h3>

      <p
        style={{
          fontFamily: 'var(--font-body)',
          fontSize: '0.95rem',
          lineHeight: 1.65,
          color: 'var(--text-soft)',
          flex: 1,
        }}
      >
        {project.desc}
      </p>

      <div
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: '0.5rem',
        }}
      >
        {project.tech.map((t) => (
          <span
            key={t}
            style={{
              fontFamily: 'var(--font-mono)',
              fontSize: '0.72rem',
              color: 'var(--text-soft)',
              background: 'rgba(255,255,255,0.08)',
              padding: '0.3rem 0.75rem',
              borderRadius: '99px',
              border: '1px solid rgba(255,255,255,0.08)',
            }}
          >
            {t}
          </span>
        ))}
      </div>

      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '0.4rem',
          fontFamily: 'var(--font-body)',
          fontWeight: 600,
          fontSize: '0.9rem',
          color: project.accent,
          marginTop: '0.25rem',
          transform: hovered ? 'translateX(5px)' : 'none',
          transition: 'transform 0.3s ease',
        }}
      >
        Lihat Detail →
      </div>
    </div>
  );
}

export default function Projects() {
  const [ref, vis] = useVisible();

  return (
    <section
      id="projects"
      ref={ref}
      style={{
        padding: 'var(--section-pad)',
        background:
          'linear-gradient(180deg, var(--bg) 0%, var(--card-bg) 100%)',
        position: 'relative',
        overflow: 'hidden',
      }}
    >
      <div
        style={{
          position: 'absolute',
          bottom: '-15%',
          left: '-8%',
          width: 400,
          height: 400,
          background: 'var(--rose)',
          borderRadius: '50%',
          opacity: 0.2,
          filter: 'blur(90px)',
        }}
      />

      <div
        style={{
          position: 'absolute',
          top: '10%',
          right: '-10%',
          width: 350,
          height: 350,
          background: 'var(--sky)',
          borderRadius: '50%',
          opacity: 0.15,
          filter: 'blur(90px)',
        }}
      />

      <div
        style={{
          maxWidth: 1100,
          margin: '0 auto',
          position: 'relative',
        }}
      >
        <div style={{ marginBottom: '3rem' }}>
          <p
            style={{
              fontFamily: 'var(--font-mono)',
              fontSize: '0.78rem',
              letterSpacing: '0.15em',
              color: 'var(--rose-deep)',
              textTransform: 'uppercase',
              marginBottom: '0.75rem',
              opacity: vis ? 1 : 0,
              transition: 'opacity 0.6s ease',
            }}
          >
            ✦ My Work
          </p>

          <h2
            style={{
              fontFamily: 'var(--font-display)',
              fontWeight: 900,
              fontSize: 'clamp(2rem, 5vw, 3.5rem)',
              lineHeight: 1.1,
              letterSpacing: '-0.02em',
              color: 'var(--text)',
              opacity: vis ? 1 : 0,
              transform: vis ? 'none' : 'translateY(20px)',
              transition: 'all 0.7s 0.1s ease',
            }}
          >
            Project <em style={{ color: 'var(--rose-deep)' }}>Saya</em>
          </h2>

          <p
            style={{
              maxWidth: 650,
              marginTop: '1rem',
              fontSize: '1rem',
              lineHeight: 1.7,
              color: 'var(--text-soft)',
              opacity: vis ? 1 : 0,
              transform: vis ? 'none' : 'translateY(20px)',
              transition: 'all 0.7s 0.2s ease',
            }}
          >
            Beberapa project yang pernah saya kerjakan dalam bidang web
            development, mobile development, dan UI design.
          </p>
        </div>

        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
            gap: '1.5rem',
          }}
        >
          {projects.map((project, i) => (
            <ProjectCard
              key={i}
              project={project}
              index={i}
              vis={vis}
            />
          ))}
        </div>
      </div>
    </section>
  );
}
